import toolz

class InaccurateLenSeq:
    def __init__(self, items, inaccurate_len):
        self.items = items
        self.inaccurate_len = inaccurate_len

    def __iter__(self):
        return iter(self.items)

    def __len__(self):
        return self.inaccurate_len

def test_bug():
    seq = InaccurateLenSeq([0, 1, 2, 3, 4], 7)
    batches = list(toolz.partition_all(10, seq))
    assert batches == [(0, 1, 2, 3, 4)]
